mapper.select:
SELECT P.PRODUCT_ID, P.PRODUCT_TITLE, COUNT(DISTINCT W.WISH_ID) AS WISH_COUNT, PI.PRODUCT_IMAGE_SAVE_NAME AS TITLE_IMAGE, MIN(PO.OPTION_PRICE) KEEP (DENSE_RANK FIRST ORDER BY PO.OPTION_ID ASC) AS PRICE, CAT_AGG.CATEGORY_NAMES AS CATEGORY_NAMES, TAG_AGG.TAG_DATA AS TAG_DATA, NVL(( SELECT ROUND(AVG(R.SCORE), 1) FROM REVIEW R JOIN ORDERDETAIL OD_SUB ON R.OD_ID = OD_SUB.OD_ID JOIN OPTIONDETAIL SUB_OD ON OD_SUB.POP_ID = SUB_OD.POP_ID WHERE SUB_OD.PRODUCT_ID = P.PRODUCT_ID AND R.REVIEW_STATUS = 1 ), 0.0) AS SCORE
FROM PRODUCT P JOIN ( SELECT CD.PRODUCT_ID, LISTAGG(C.CATEGORY_NAME, ',') WITHIN GROUP (ORDER BY C.CATEGORY_ID) AS CATEGORY_NAMES FROM CATEGORYDETAIL CD JOIN CATEGORY C ON CD.CATEGORY_ID = C.CATEGORY_ID GROUP BY CD.PRODUCT_ID ) CAT_AGG ON P.PRODUCT_ID = CAT_AGG.PRODUCT_ID
LEFT JOIN ( SELECT TD.PRODUCT_ID, LISTAGG(T.TAG_NAME || '|' || T.TAG_COLOR, ',') WITHIN GROUP (ORDER BY T.TAG_ID) AS TAG_DATA FROM TAGDETAIL TD JOIN TAG T ON TD.TAG_ID = T.TAG_ID GROUP BY TD.PRODUCT_ID ) TAG_AGG ON P.PRODUCT_ID = TAG_AGG.PRODUCT_ID
JOIN OPTIONDETAIL OD ON P.PRODUCT_ID = OD.PRODUCT_ID JOIN PRODUCTOPTION PO ON OD.OPTION_ID = PO.OPTION_ID LEFT JOIN PRODUCTIMAGE PI ON P.PRODUCT_ID = PI.PRODUCT_ID AND PI.PRODUCT_TITLE_IMAGE = 0 LEFT JOIN WISH W ON P.PRODUCT_ID = W.PRODUCT_ID
AND ( P.PRODUCT_TITLE LIKE '%' || #{search.keyword} || '%' OR P.PRODUCT_NAME LIKE '%' || #{search.keyword} || '%' OR CAT_AGG.CATEGORY_NAMES LIKE '%' || #{search.keyword} || '%' OR TAG_AGG.TAG_DATA LIKE '%' || #{search.keyword} || '%' )
AND CAT_AGG.PRODUCT_ID IN ( SELECT PRODUCT_ID FROM CATEGORYDETAIL WHERE CATEGORY_ID IN
#{catId}
)
AND TAG_AGG.PRODUCT_ID IN ( SELECT PRODUCT_ID FROM TAGDETAIL WHERE TAG_ID IN
#{tagId}
)
GROUP BY P.PRODUCT_ID, P.PRODUCT_TITLE, PI.PRODUCT_IMAGE_SAVE_NAME, CAT_AGG.CATEGORY_NAMES, TAG_AGG.TAG_DATA ORDER BY COUNT(DISTINCT W.WISH_ID) DESC
OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(DISTINCT P.PRODUCT_ID) FROM PRODUCT P
JOIN ( SELECT CD.PRODUCT_ID, LISTAGG(C.CATEGORY_NAME, ',') WITHIN GROUP (ORDER BY C.CATEGORY_ID) AS CATEGORY_NAMES FROM CATEGORYDETAIL CD JOIN CATEGORY C ON CD.CATEGORY_ID = C.CATEGORY_ID GROUP BY CD.PRODUCT_ID ) CAT_AGG ON P.PRODUCT_ID = CAT_AGG.PRODUCT_ID
LEFT JOIN ( SELECT TD.PRODUCT_ID, LISTAGG(T.TAG_NAME || '|' || T.TAG_COLOR, ',') WITHIN GROUP (ORDER BY T.TAG_ID) AS TAG_DATA FROM TAGDETAIL TD JOIN TAG T ON TD.TAG_ID = T.TAG_ID GROUP BY TD.PRODUCT_ID ) TAG_AGG ON P.PRODUCT_ID = TAG_AGG.PRODUCT_ID
AND ( P.PRODUCT_TITLE LIKE '%' || #{keyword} || '%' OR P.PRODUCT_NAME LIKE '%' || #{keyword} || '%' OR CAT_AGG.CATEGORY_NAMES LIKE '%' || #{keyword} || '%' OR TAG_AGG.TAG_DATA LIKE '%' || #{keyword} || '%' )
AND P.PRODUCT_ID IN ( SELECT PRODUCT_ID FROM CATEGORYDETAIL WHERE CATEGORY_ID IN
#{catId}
)
AND P.PRODUCT_ID IN ( SELECT PRODUCT_ID FROM TAGDETAIL WHERE TAG_ID IN
#{tagId}
)
